import { useState } from "react";

const G = "linear-gradient(135deg, rgb(148,0,211), rgb(237,128,233))";
const gradText = { background: G, WebkitBackgroundClip: "text", WebkitTextFillColor: "transparent", backgroundClip: "text" };

const isEmail = (v) => /\S+@\S+\.\S+/.test(v);
const isPhone = (v) => /^[6-9]\d{9}$/.test(v.replace(/\s/g, ""));

export default function ForgotPasswordPopup({ onClose }) {
  const [step, setStep] = useState("input"); // input | emailSent | otp | success
  const [value, setValue] = useState("");
  const [otp, setOtp] = useState(["", "", "", ""]);
  const [error, setError] = useState("");

  const handleSubmit = () => {
    setError("");
    if (!value.trim()) { setError("Please enter email or phone number"); return; }
    if (isEmail(value)) { setStep("emailSent"); }
    else if (isPhone(value)) { setStep("otp"); }
    else { setError("Enter a valid email or 10-digit mobile number"); }
  };

  const handleOtpChange = (val, i) => {
    const newOtp = [...otp];
    newOtp[i] = val.replace(/\D/, "");
    setOtp(newOtp);
    if (val && i < 3) document.getElementById(`otp-${i + 1}`)?.focus();
  };

  const verifyOtp = () => {
    if (otp.join("").length < 4) { setError("Enter all 4 digits"); return; }
    if (otp.join("") === "1234") { setStep("success"); } // replace with real API
    else { setError("Incorrect OTP. Please try again."); }
  };

  return (
    <div style={{ position:"fixed", inset:0, background:"rgba(80,0,130,0.25)", backdropFilter:"blur(4px)", zIndex:100, display:"flex", alignItems:"center", justifyContent:"center", padding:"20px" }}
      onClick={(e) => e.target === e.currentTarget && onClose()}>

      <div style={{ background:"#fff", borderRadius:"20px", padding:"36px 32px", width:"100%", maxWidth:"360px", textAlign:"center", position:"relative", animation:"popIn 0.25s ease" }}>

        <button onClick={onClose} style={{ position:"absolute", top:14, right:18, background:"none", border:"none", fontSize:20, cursor:"pointer", color:"#aaa" }}>✕</button>

        {/* STEP 1: Input */}
        {step === "input" && <>
          <div style={{ fontSize:40, marginBottom:10 }}>🔐</div>
          <h3 style={{ ...gradText, fontSize:20, marginBottom:6 }}>Forgot Password?</h3>
          <p style={{ fontSize:13, color:"#999", marginBottom:20 }}>Enter your email or phone number.<br/>We'll send a reset link or OTP.</p>
          {error && <div style={{ color:"red", fontSize:13, marginBottom:10, textAlign:"left" }}>{error}</div>}
          <input value={value} onChange={(e) => setValue(e.target.value)} placeholder="Email or Phone number"
            style={{ width:"100%", height:48, padding:"0 14px", borderRadius:8, border:"1.5px solid #e0c8f8", outline:"none", marginBottom:14, fontSize:14 }} />
          <button onClick={handleSubmit} style={{ width:"100%", height:48, background:G, color:"#fff", border:"none", borderRadius:8, fontWeight:600, fontSize:15, cursor:"pointer" }}>Send Reset</button>
        </>}

        {/* STEP 2a: Email Sent */}
        {step === "emailSent" && <>
          <div style={{ fontSize:40, marginBottom:10 }}>📧</div>
          <h3 style={{ ...gradText, fontSize:20, marginBottom:6 }}>Check Your Email</h3>
          <p style={{ fontSize:13, color:"#999", marginBottom:20 }}>We've sent a password reset link to<br/><strong>{value}</strong><br/><br/>Click the link to reset your password.</p>
          <button onClick={onClose} style={{ width:"100%", height:48, background:G, color:"#fff", border:"none", borderRadius:8, fontWeight:600, cursor:"pointer" }}>Done</button>
          <p style={{ fontSize:13, color:"#999", marginTop:12 }}>Didn't receive? <span onClick={() => alert("Email resent!")} style={{ ...gradText, cursor:"pointer", fontWeight:600 }}>Resend Email</span></p>
        </>}

        {/* STEP 2b: OTP */}
        {step === "otp" && <>
          <div style={{ fontSize:40, marginBottom:10 }}>📱</div>
          <h3 style={{ ...gradText, fontSize:20, marginBottom:6 }}>Enter OTP</h3>
          <p style={{ fontSize:13, color:"#999", marginBottom:16 }}>We've sent a 4-digit OTP to<br/><strong>+91 {value}</strong></p>
          {error && <div style={{ color:"red", fontSize:13, marginBottom:10 }}>{error}</div>}
          <div style={{ display:"flex", gap:10, justifyContent:"center", marginBottom:14 }}>
            {otp.map((d, i) => (
              <input key={i} id={`otp-${i}`} value={d} maxLength={1} inputMode="numeric"
                onChange={(e) => handleOtpChange(e.target.value, i)}
                onKeyDown={(e) => e.key === "Backspace" && !d && i > 0 && document.getElementById(`otp-${i-1}`)?.focus()}
                style={{ width:52, height:56, textAlign:"center", fontSize:22, fontWeight:700, borderRadius:10, border:"1.5px solid #e0c8f8", outline:"none" }} />
            ))}
          </div>
          <p style={{ fontSize:13, color:"#999", marginBottom:14 }}>Didn't get OTP? <span onClick={() => { setOtp(["","","",""]); alert("OTP resent!"); }} style={{ ...gradText, cursor:"pointer", fontWeight:600 }}>Resend OTP</span></p>
          <button onClick={verifyOtp} style={{ width:"100%", height:48, background:G, color:"#fff", border:"none", borderRadius:8, fontWeight:600, cursor:"pointer" }}>Verify & Login</button>
        </>}

        {/* STEP 3: Success */}
        {step === "success" && <>
          <div style={{ fontSize:56, marginBottom:12 }}>✅</div>
          <h3 style={{ color:"#2e7d32", fontSize:20, fontWeight:700, marginBottom:6 }}>Login Successful!</h3>
          <p style={{ fontSize:13, color:"#999", marginBottom:20 }}>You have been verified and logged in successfully.</p>
          <button onClick={onClose} style={{ width:"100%", height:48, background:G, color:"#fff", border:"none", borderRadius:8, fontWeight:600, cursor:"pointer" }}>Go to Home</button>
        </>}

      </div>
    </div>
  );
}
